entries.content:
Add `Current state`, `implementation details`, `acceptance criteria` for `design/feature_descriptions/B_122_connect_to_sentry_fails.md`.&#x20;
update the field `status` in the markdown feature description file to `ready for implementation`.

Read all referenced files before you begin except `agents` files. it is possible that the file is not yet written. &#x20;
Ask any question if something is ambiguous or not yet clear.
Be brief, but never compress away the subject, timing, or causal chain. Define ambiguous technical phrases. use $caveman skill.

Do not stage or commit changes. You have no need for get at this time.

import type { SentryIssueEvent, SentryIssueSummary, SentryStackFrame } from './sentry_types'
import { normalizeSentryBaseUrl } from './sentry_types'

export interface SentryApiRequest {
    apiBaseUrl: string
    apiToken: string
    environment: string
    organization: string
    project: string
}

export interface SentryApiClientDependencies {
    fetch: typeof fetch
}

export class SentryApiError extends Error {
    readonly status: number

    constructor(message: string, status: number) {
        super(message)
        this.name = 'SentryApiError'
        this.status = status
    }
}

function requireRecord(value: unknown, context: string): Record<string, unknown> {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed Sentry ${context}`)

    return value as Record<string, unknown>
}

function optionalString(value: unknown) {
    return typeof value === 'string' && value.length > 0 ? value : null
}

function optionalNumber(value: unknown) {
    return typeof value === 'number' && Number.isFinite(value) ? value : null
}

function issueSummary(value: unknown): SentryIssueSummary {
    const issue = requireRecord(value, 'issue response')
    const id = optionalString(issue.id)
    const title = optionalString(issue.title)
    if (!id) throw new Error('Malformed Sentry issue response: id is required')
    if (!title) throw new Error(`Malformed Sentry issue response for ${id}: title is required`)

    return {
        count: optionalString(issue.count),
        culprit: optionalString(issue.culprit),
        firstSeen: optionalString(issue.firstSeen),
        id,
        lastSeen: optionalString(issue.lastSeen),
        link: optionalString(issue.permalink),
        title,
    }
}

function stackFrames(entries: unknown): SentryStackFrame[] {
    if (!Array.isArray(entries)) return []

    return entries.flatMap((entryValue) => {
        if (!entryValue || typeof entryValue !== 'object' || Array.isArray(entryValue)) return []
        const entry = entryValue as Record<string, unknown>
        if (entry.type !== 'exception') return []
        const data = entry.data
        if (!data || typeof data !== 'object' || Array.isArray(data)) return []
        const values = (data as Record<string, unknown>).values
        if (!Array.isArray(values)) return []

        return values.flatMap((exceptionValue) => {
            if (!exceptionValue || typeof exceptionValue !== 'object' || Array.isArray(exceptionValue)) return []
            const stacktrace = (exceptionValue as Record<string, unknown>).stacktrace
            if (!stacktrace || typeof stacktrace !== 'object' || Array.isArray(stacktrace)) return []
            const frames = (stacktrace as Record<string, unknown>).frames
            if (!Array.isArray(frames)) return []

            return frames.flatMap((frameValue) => {
                if (!frameValue || typeof frameValue !== 'object' || Array.isArray(frameValue)) return []
                const frame = frameValue as Record<string, unknown>
                if (frame.inApp !== true) return []

                return [{
                    columnNumber: optionalNumber(frame.colNo),
                    fileName: optionalString(frame.filename),
                    functionName: optionalString(frame.function),
                    lineNumber: optionalNumber(frame.lineNo),
                }]
            })
        })
    })
}

function releaseVersion(value: unknown) {
    if (typeof value === 'string') return optionalString(value)
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null

    return optionalString((value as Record<string, unknown>).version)
}

function eventEnvironment(event: Record<string, unknown>) {
    const directEnvironment = optionalString(event.environment)
    if (directEnvironment) return directEnvironment
    if (!Array.isArray(event.tags)) return null

    const environmentTag = event.tags.find((tagValue) => {
        if (!tagValue || typeof tagValue !== 'object' || Array.isArray(tagValue)) return false
        return (tagValue as Record<string, unknown>).key === 'environment'
    }) as Record<string, unknown> | undefined

    return optionalString(environmentTag?.value)
}

function issueEvent(value: unknown): SentryIssueEvent {
    const event = requireRecord(value, 'event response')
    const eventId = optionalString(event.eventID) ?? optionalString(event.id)
    if (!eventId) throw new Error('Malformed Sentry event response: event ID is required')

    return {
        environment: eventEnvironment(event),
        eventId,
        message: optionalString(event.message),
        release: releaseVersion(event.release),
        stackFrames: stackFrames(event.entries),
    }
}

function nextPageUrl(linkHeader: string | null) {
    if (!linkHeader) return null

    const nextLink = linkHeader.split(',').find((part) => part.includes('rel="next"') && part.includes('results="true"'))
    return nextLink?.match(/<([^>]+)>/u)?.[1] ?? null
}

function projectUrl(request: SentryApiRequest) {
    const baseUrl = normalizeSentryBaseUrl(request.apiBaseUrl)
    const organization = encodeURIComponent(request.organization)
    const project = encodeURIComponent(request.project)

    return `${baseUrl}/api/0/projects/${organization}/${project}`
}

export class SentryApiClient {
    private readonly fetchRequest: typeof fetch

    constructor(dependencies: SentryApiClientDependencies = { fetch }) {
        this.fetchRequest = dependencies.fetch
    }

    async validateProject(request: SentryApiRequest) {
        const url = projectUrl(request)
        await this.requestJson(url, request.apiToken)
    }

    async listUnresolvedIssues(request: SentryApiRequest) {
        const url = new URL(`${projectUrl(request)}/issues/`)
        url.searchParams.set('limit', '100')
        url.searchParams.set('query', `is:unresolved environment:"${request.environment.replace(/"/gu, '\\"')}"`)
        const issues: SentryIssueSummary[] = []
        let pageUrl: string | null = url.toString()

        while (pageUrl) {
            const response = await this.request(pageUrl, request.apiToken)
            const body: unknown = await response.json()
            if (!Array.isArray(body)) throw new Error('Malformed Sentry issue list response')
            issues.push(...body.map(issueSummary))
            pageUrl = nextPageUrl(response.headers.get('Link'))
        }

        return issues
    }

    async loadRecommendedEvent(request: SentryApiRequest, issueId: string) {
        const baseUrl = normalizeSentryBaseUrl(request.apiBaseUrl)
        const organization = encodeURIComponent(request.organization)
        const id = encodeURIComponent(issueId)
        const url = new URL(`${baseUrl}/api/0/organizations/${organization}/issues/${id}/events/recommended/`)
        url.searchParams.append('environment', request.environment)

        return issueEvent(await this.requestJson(url.toString(), request.apiToken))
    }

    private async requestJson(url: string, apiToken: string): Promise<unknown> {
        const response = await this.request(url, apiToken)

        return response.json()
    }

    private async request(url: string, apiToken: string) {
        const response = await this.fetchRequest(url, {
            headers: {
                Accept: 'application/json',
                Authorization: `Bearer ${apiToken}`,
            },
        })
        if (response.ok) return response

        const retryAfter = response.headers.get('Retry-After')
        const retryMessage = retryAfter ? ` Retry after ${retryAfter} seconds.` : ''
        throw new SentryApiError(`Sentry request failed with status ${response.status}.${retryMessage}`, response.status)
    }
}

export const sentryApiClient = new SentryApiClient()

import type { ProjectReference } from '../../data/data_types'
import { register } from '../service_injector'
import { SentryApiClient, SentryApiError, sentryApiClient } from './sentry_api_client'
import {
    createDefaultSentryProjectSettings,
    normalizeSentryBaseUrl,
    type SentryProjectSettings,
} from './sentry_types'

export const SENTRY_CONNECTION_STORAGE_KEY = 'md2.sentry.connections'

export interface SentryConnectionSnapshot {
    errorMessage: string | null
    isAuthenticated: boolean
    isConnecting: boolean
    projectId: string | null
    settings: SentryProjectSettings
}

export interface SentryConnectionServiceDependencies {
    apiClient: Pick<SentryApiClient, 'validateProject'>
    storage: Pick<Storage, 'getItem' | 'setItem'>
}

type StoredConnections = Record<string, SentryProjectSettings>

function errorMessage(error: unknown) {
    return error instanceof Error ? error.message : 'Unexpected Sentry connection error'
}

function readConnections(storage: Pick<Storage, 'getItem'>): StoredConnections {
    const stored = storage.getItem(SENTRY_CONNECTION_STORAGE_KEY)
    if (!stored) return {}

    const parsed: unknown = JSON.parse(stored)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Stored Sentry connections are invalid')

    return parsed as StoredConnections
}

function normalizedSettings(settings: SentryProjectSettings): SentryProjectSettings {
    const apiToken = settings.apiToken.trim()
    const organization = settings.organization.trim()
    const project = settings.project.trim()
    const environment = settings.environment.trim()
    if (!apiToken) throw new Error('Sentry API token is required')
    if (!organization) throw new Error('Sentry organization is required')
    if (!project) throw new Error('Sentry project is required')
    if (!environment) throw new Error('Sentry environment is required')

    return {
        ...settings,
        apiBaseUrl: normalizeSentryBaseUrl(settings.apiBaseUrl),
        apiToken,
        environment,
        organization,
        project,
    }
}

export class SentryConnectionService extends EventTarget {
    private apiClient: Pick<SentryApiClient, 'validateProject'> | null = null
    private projectId: string | null = null
    private snapshot: SentryConnectionSnapshot = {
        errorMessage: null,
        isAuthenticated: false,
        isConnecting: false,
        projectId: null,
        settings: createDefaultSentryProjectSettings(),
    }
    private storage: Pick<Storage, 'getItem' | 'setItem'> | null = null

    constructor() {
        super()
        register('sentryConnectionService', this)
    }

    init(dependencies: SentryConnectionServiceDependencies) {
        this.apiClient = dependencies.apiClient
        this.storage = dependencies.storage
        this.setProject(null)
    }

    getSnapshot() {
        return this.snapshot
    }

    setProject(project: ProjectReference | null) {
        const projectId = project?.id ?? null
        if (projectId === this.projectId && this.snapshot.projectId === projectId) return

        this.projectId = projectId
        const settings = projectId ? this.readProjectSettings(projectId) : createDefaultSentryProjectSettings()
        this.setSnapshot({
            errorMessage: null,
            isAuthenticated: settings.apiToken.length > 0,
            isConnecting: false,
            projectId,
            settings,
        })
    }

    async connect(settings: SentryProjectSettings) {
        const projectId = this.requireProjectId()
        const apiClient = this.requireApiClient()
        const nextSettings = normalizedSettings(settings)
        this.setSnapshot({ errorMessage: null, isConnecting: true })

        try {
            await apiClient.validateProject(nextSettings)
            if (projectId !== this.projectId) return
            this.writeProjectSettings(projectId, nextSettings)
            this.setSnapshot({
                errorMessage: null,
                isAuthenticated: true,
                isConnecting: false,
                settings: nextSettings,
            })
        } catch (error) {
            if (projectId !== this.projectId) return
            if (error instanceof SentryApiError && (error.status === 401 || error.status === 403)) {
                this.handleUnauthorized()
                return
            }
            this.setSnapshot({
                errorMessage: errorMessage(error),
                isConnecting: false,
            })
        }
    }

    saveSettings(settings: SentryProjectSettings) {
        const projectId = this.requireProjectId()
        const current = this.snapshot.settings
        const identityChanged = normalizeSentryBaseUrl(current.apiBaseUrl) !== normalizeSentryBaseUrl(settings.apiBaseUrl)
            || current.organization.trim() !== settings.organization.trim()
            || current.project.trim() !== settings.project.trim()
        const nextSettings = normalizedSettings({
            ...settings,
            firstImportConfirmed: identityChanged ? false : settings.firstImportConfirmed,
        })
        this.writeProjectSettings(projectId, nextSettings)
        this.setSnapshot({ settings: nextSettings })
    }

    disconnect() {
        const projectId = this.requireProjectId()
        const settings = { ...this.snapshot.settings, apiToken: '', automaticImport: false }
        this.writeProjectSettings(projectId, settings)
        this.setSnapshot({ errorMessage: null, isAuthenticated: false, isConnecting: false, settings })
    }

    handleUnauthorized() {
        const projectId = this.requireProjectId()
        const settings = { ...this.snapshot.settings, apiToken: '', automaticImport: false }
        this.writeProjectSettings(projectId, settings)
        this.setSnapshot({
            errorMessage: 'Sentry authorization expired. Connect again.',
            isAuthenticated: false,
            isConnecting: false,
            settings,
        })
    }

    handleApiError(error: unknown) {
        if (error instanceof SentryApiError && (error.status === 401 || error.status === 403)) this.handleUnauthorized()
    }

    private readProjectSettings(projectId: string) {
        const { storage } = this.requireDependencies()
        const stored = readConnections(storage)[projectId]

        return stored ? { ...createDefaultSentryProjectSettings(), ...stored } : createDefaultSentryProjectSettings()
    }

    private writeProjectSettings(projectId: string, settings: SentryProjectSettings) {
        const { storage } = this.requireDependencies()
        const connections = readConnections(storage)
        storage.setItem(SENTRY_CONNECTION_STORAGE_KEY, JSON.stringify({ ...connections, [projectId]: settings }))
    }

    private requireApiClient() {
        if (!this.apiClient) throw new Error('Sentry connection service API client is not initialized')

        return this.apiClient
    }

    private requireDependencies() {
        if (!this.storage) throw new Error('Sentry connection service storage is not initialized')

        return { storage: this.storage }
    }

    private requireProjectId() {
        if (!this.projectId) throw new Error('Cannot configure Sentry before a project is open')

        return this.projectId
    }

    private setSnapshot(snapshot: Partial<SentryConnectionSnapshot>) {
        this.snapshot = { ...this.snapshot, ...snapshot }
        this.dispatchEvent(new CustomEvent<SentryConnectionSnapshot>('changed', { detail: this.snapshot }))
    }
}

export function initDefaultSentryConnectionService(service: SentryConnectionService) {
    service.init({ apiClient: sentryApiClient, storage: window.localStorage })

    return service
}

export const sentryConnectionService = new SentryConnectionService()

import type { CardType } from '../../data/data_types'

export const DEFAULT_SENTRY_BASE_URL = 'https://sentry.io'
export const DEFAULT_SENTRY_ENVIRONMENT = 'production'

export interface SentryProjectSettings {
    apiBaseUrl: string
    apiToken: string
    automaticImport: boolean
    cardState: string
    cardType: CardType | ''
    environment: string
    firstImportConfirmed: boolean
    organization: string
    project: string
}

export interface SentryIssueSummary {
    count: string | null
    culprit: string | null
    firstSeen: string | null
    id: string
    lastSeen: string | null
    link: string | null
    title: string
}

export interface SentryStackFrame {
    columnNumber: number | null
    fileName: string | null
    functionName: string | null
    lineNumber: number | null
}

export interface SentryIssueEvent {
    environment: string | null
    eventId: string
    message: string | null
    release: string | null
    stackFrames: SentryStackFrame[]
}

export interface SentryIssueImport {
    event: SentryIssueEvent
    issue: SentryIssueSummary
}

export function createDefaultSentryProjectSettings(): SentryProjectSettings {
    return {
        apiBaseUrl: DEFAULT_SENTRY_BASE_URL,
        apiToken: '',
        automaticImport: false,
        cardState: '',
        cardType: '',
        environment: DEFAULT_SENTRY_ENVIRONMENT,
        firstImportConfirmed: false,
        organization: '',
        project: '',
    }
}

export function normalizeSentryBaseUrl(baseUrl: string) {
    const normalized = baseUrl.trim().replace(/\/+$/u, '')
    if (!normalized) throw new Error('Sentry API base URL is required')

    const parsed = new URL(normalized)
    if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
        throw new Error('Sentry API base URL must use HTTP or HTTPS')
    }

    return parsed.toString().replace(/\/$/u, '')
}

export function sentryIdentityKey(baseUrl: string, organization: string, issueId: string) {
    return `${normalizeSentryBaseUrl(baseUrl).toLowerCase()}\n${organization.trim().toLowerCase()}\n${issueId.trim()}`
}

import {
    Alert,
    Box,
    Button,
    FormControl,
    FormControlLabel,
    InputLabel,
    MenuItem,
    Select,
    Stack,
    Switch,
    TextField,
    Typography,
    type SelectChangeEvent,
} from '@mui/material'
import { useState, type ChangeEvent } from 'react'
import { useProjectConfig } from '../hooks/use_project_config'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { useProjectReference } from '../hooks/use_project_reference'
import { useSentryConnection } from '../hooks/use_sentry_connection'
import { useSentryImport } from '../hooks/use_sentry_import'
import { sentryConnectionService, type SentryConnectionSnapshot } from '../../services/sentry/sentry_connection_service'
import { sentryImportService } from '../../services/sentry/sentry_import_service'
import type { SentryProjectSettings } from '../../services/sentry/sentry_types'

const SENTRY_CONFIG_SECTION_ID = 'sentry'

function settingsComplete(settings: SentryProjectSettings) {
    return settings.apiBaseUrl.trim().length > 0
        && settings.apiToken.trim().length > 0
        && settings.organization.trim().length > 0
        && settings.project.trim().length > 0
        && settings.environment.trim().length > 0
        && settings.cardType.length > 0
        && settings.cardState.trim().length > 0
}

interface SentryConfigFormProps {
    connection: SentryConnectionSnapshot
}

function SentryConfigForm({ connection }: SentryConfigFormProps) {
    const importState = useSentryImport()
    const project = useProjectReference()
    const projectConfig = useProjectConfig()
    const readOnly = useProjectReadOnly()
    const [draft, setDraft] = useState(connection.settings)
    const controlsDisabled = !project || readOnly || connection.isConnecting
    const canConnect = !controlsDisabled && settingsComplete(draft)
    const canImport = !controlsDisabled && connection.isAuthenticated && settingsComplete(connection.settings) && !importState.isPolling

    const updateTextField = (field: keyof SentryProjectSettings) => (event: ChangeEvent<HTMLInputElement>) => {
        setDraft((current) => ({ ...current, [field]: event.target.value }))
    }
    const handleCardTypeChange = (event: SelectChangeEvent) => {
        setDraft((current) => ({ ...current, cardType: event.target.value }))
    }
    const handleCardStateChange = (event: SelectChangeEvent) => {
        setDraft((current) => ({ ...current, cardState: event.target.value }))
    }
    const handleConnect = () => {
        void sentryConnectionService.connect(draft)
    }
    const handleDisconnect = () => {
        sentryConnectionService.disconnect()
        setDraft({ ...connection.settings, apiToken: '', automaticImport: false })
    }
    const handleAutomaticImportChange = (event: ChangeEvent<HTMLInputElement>) => {
        sentryConnectionService.saveSettings({ ...connection.settings, automaticImport: event.target.checked })
    }
    const handleImportNow = () => {
        void sentryImportService.importNow()
    }

    return (
        <Box aria-labelledby="sentry-config-heading" component="section" id={SENTRY_CONFIG_SECTION_ID}>
            <Stack spacing={3}>
                <Typography component="h3" id="sentry-config-heading" variant="h6">Sentry</Typography>
                <Typography color="text.secondary" variant="body2">
                    Connect this MDÂ² project to one Sentry project. Credentials stay in this browser.
                </Typography>
                {!project ? <Alert severity="info">Open a project to configure Sentry imports.</Alert> : null}
                <TextField disabled={controlsDisabled} label="Sentry API base URL" onChange={updateTextField('apiBaseUrl')} size="small" value={draft.apiBaseUrl} />
                <TextField disabled={controlsDisabled} label="Organization slug" onChange={updateTextField('organization')} size="small" value={draft.organization} />
                <TextField disabled={controlsDisabled} label="Project slug" onChange={updateTextField('project')} size="small" value={draft.project} />
                <TextField disabled={controlsDisabled} label="Environment" onChange={updateTextField('environment')} size="small" value={draft.environment} />
                <TextField disabled={controlsDisabled} label="Sentry API token" onChange={updateTextField('apiToken')} size="small" type="password" value={draft.apiToken} />
                <FormControl disabled={controlsDisabled} size="small">
                    <InputLabel id="sentry-card-type-label">Target card type</InputLabel>
                    <Select label="Target card type" labelId="sentry-card-type-label" onChange={handleCardTypeChange} value={draft.cardType}>
                        {(projectConfig?.cardTypes ?? []).map(({ label, type }) => <MenuItem key={type} value={type}>{label}</MenuItem>)}
                    </Select>
                </FormControl>
                <FormControl disabled={controlsDisabled} size="small">
                    <InputLabel id="sentry-card-state-label">Target card state</InputLabel>
                    <Select label="Target card state" labelId="sentry-card-state-label" onChange={handleCardStateChange} value={draft.cardState}>
                        {(projectConfig?.states ?? []).map(({ state }) => <MenuItem key={state} value={state}>{state}</MenuItem>)}
                    </Select>
                </FormControl>
                {connection.errorMessage ? <Alert severity="error">{connection.errorMessage}</Alert> : null}
                <Stack direction="row" spacing={1}>
                    <Button disabled={!canConnect} onClick={handleConnect} variant="contained">
                        {connection.isConnecting ? 'Connecting...' : connection.isAuthenticated ? 'Reconnect' : 'Connect'}
                    </Button>
                    <Button disabled={controlsDisabled || !connection.isAuthenticated} onClick={handleDisconnect} variant="outlined">Disconnect</Button>
                </Stack>
                <FormControlLabel
                    control={(
                        <Switch
                            checked={connection.settings.automaticImport}
                            disabled={!canImport}
                            onChange={handleAutomaticImportChange}
                        />
                    )}
                    label="Enable automatic import"
                />
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                    <Button disabled={!canImport} onClick={handleImportNow} variant="outlined">Import now</Button>
                    {importState.isPolling ? <Typography color="text.secondary" variant="body2">Checking Sentry...</Typography> : null}
                </Stack>
                {importState.lastImportCount !== null ? (
                    <Typography color="text.secondary" variant="body2">Last import created {importState.lastImportCount} card(s).</Typography>
                ) : null}
                {importState.lastSuccessfulPollAt ? (
                    <Typography color="text.secondary" variant="body2">Last successful poll: {importState.lastSuccessfulPollAt}</Typography>
                ) : null}
                {importState.latestError ? <Alert severity="error">Latest import error: {importState.latestError}</Alert> : null}
            </Stack>
        </Box>
    )
}

export function SentryConfigSection() {
    const connection = useSentryConnection()

    return <SentryConfigForm connection={connection} key={connection.projectId ?? 'no-project'} />
}

import { useSyncExternalStore } from 'react'
import {
    sentryConnectionService,
    type SentryConnectionService,
    type SentryConnectionSnapshot,
} from '../../services/sentry/sentry_connection_service'

export function useSentryConnection(service: SentryConnectionService = sentryConnectionService): SentryConnectionSnapshot {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => service.getSnapshot(),
        () => service.getSnapshot(),
    )
}

import { describe, expect, it, vi } from 'vitest'
import { SentryApiClient, SentryApiError, type SentryApiRequest } from './sentry_api_client'

const request: SentryApiRequest = {
    apiBaseUrl: 'https://sentry.example.com/',
    apiToken: 'secret-token',
    environment: 'production',
    organization: 'acme',
    project: 'frontend',
}

describe('SentryApiClient', () => {
    it('validates configured organization and project with bearer authentication', async () => {
        const fetchRequest = vi.fn(async () => new Response('{}'))
        const client = new SentryApiClient({ fetch: fetchRequest })

        await client.validateProject(request)

        expect(fetchRequest).toHaveBeenCalledWith(
            'https://sentry.example.com/api/0/projects/acme/frontend',
            { headers: { Accept: 'application/json', Authorization: 'Bearer secret-token' } },
        )
    })

    it('loads every unresolved environment page through Sentry cursor links', async () => {
        const firstHeaders = new Headers({Link: '<https://sentry.example.com/api/0/projects/acme/frontend/issues/?cursor=next>; rel="next"; results="true"'})
        const fetchRequest = vi.fn()
            .mockResolvedValueOnce(new Response(JSON.stringify([{ id: '1', title: 'First' }]), { headers: firstHeaders }))
            .mockResolvedValueOnce(new Response(JSON.stringify([{ id: '2', title: 'Second' }])))
        const client = new SentryApiClient({ fetch: fetchRequest })

        const issues = await client.listUnresolvedIssues(request)

        const firstUrl = new URL(fetchRequest.mock.calls[0][0] as string)
        expect(firstUrl.pathname).toBe('/api/0/projects/acme/frontend/issues/')
        expect(firstUrl.searchParams.get('query')).toBe('is:unresolved environment:"production"')
        expect(firstUrl.searchParams.get('limit')).toBe('100')
        expect(fetchRequest.mock.calls[1][0]).toContain('cursor=next')
        expect(issues.map(({ id }) => id)).toEqual(['1', '2'])
    })

    it('loads and sanitizes the recommended event', async () => {
        const event = {
            entries: [{
                data: {
                    values: [{
                        stacktrace: {
                            frames: [
                                { filename: 'vendor.js', function: 'vendor', inApp: false, vars: { token: 'secret' } },
                                { colNo: 4, filename: 'app.ts', function: 'run', inApp: true, lineNo: 12, vars: { token: 'secret' } },
                            ],
                        },
                    }],
                },
                type: 'exception',
            }],
            eventID: 'event-1',
            message: 'Failed',
            release: { version: '1.2.3' },
            request: { cookies: [['session', 'secret']], data: 'secret body' },
            tags: [{ key: 'environment', value: 'production' }],
            user: { email: 'person@example.com' },
        }
        const fetchRequest = vi.fn<typeof fetch>(async () => new Response(JSON.stringify(event)))
        const client = new SentryApiClient({ fetch: fetchRequest })

        const result = await client.loadRecommendedEvent(request, '123')

        expect(fetchRequest.mock.calls[0][0]).toContain('/api/0/organizations/acme/issues/123/events/recommended/')
        expect(result).toEqual({
            environment: 'production',
            eventId: 'event-1',
            message: 'Failed',
            release: '1.2.3',
            stackFrames: [{ columnNumber: 4, fileName: 'app.ts', functionName: 'run', lineNumber: 12 }],
        })
        expect(JSON.stringify(result)).not.toContain('secret')
        expect(JSON.stringify(result)).not.toContain('person@example.com')
    })

    it('tolerates malformed optional event fields', async () => {
        const fetchRequest = vi.fn(async () => new Response(JSON.stringify({ entries: 'bad', eventID: 'event-1', release: 12 })))
        const client = new SentryApiClient({ fetch: fetchRequest })

        await expect(client.loadRecommendedEvent(request, '123')).resolves.toEqual({
            environment: null,
            eventId: 'event-1',
            message: null,
            release: null,
            stackFrames: [],
        })
    })

    it('reports rate limits with retry timing', async () => {
        const fetchRequest = vi.fn(async () => new Response('', { headers: { 'Retry-After': '30' }, status: 429 }))
        const client = new SentryApiClient({ fetch: fetchRequest })

        await expect(client.listUnresolvedIssues(request)).rejects.toEqual(
            new SentryApiError('Sentry request failed with status 429. Retry after 30 seconds.', 429),
        )
    })
})

import { describe, expect, it, vi } from 'vitest'
import type { ProjectReference } from '../../data/data_types'
import { SentryApiError } from './sentry_api_client'
import {
    SENTRY_CONNECTION_STORAGE_KEY,
    SentryConnectionService,
    type SentryConnectionServiceDependencies,
} from './sentry_connection_service'
import { createDefaultSentryProjectSettings, type SentryProjectSettings } from './sentry_types'

function createMemoryStorage() {
    const values = new Map<string, string>()

    return {
        getItem: (key: string) => values.get(key) ?? null,
        setItem: (key: string, value: string) => values.set(key, value),
    }
}

function project(id: string): ProjectReference {
    return { branch: 'main', id }
}

function configuredSettings(overrides: Partial<SentryProjectSettings> = {}): SentryProjectSettings {
    return {
        ...createDefaultSentryProjectSettings(),
        apiBaseUrl: 'https://sentry.example.com/',
        apiToken: ' secret ',
        cardState: 'to fix',
        cardType: 'bug',
        environment: ' production ',
        organization: ' acme ',
        project: ' frontend ',
        ...overrides,
    }
}

function createService(overrides: Partial<SentryConnectionServiceDependencies> = {}) {
    const dependencies = {
        apiClient: { validateProject: vi.fn(async () => undefined) },
        storage: createMemoryStorage(),
        ...overrides,
    }
    const service = new SentryConnectionService()
    service.init(dependencies)

    return { dependencies, service }
}

describe('SentryConnectionService', () => {
    it('validates, normalizes, and persists project-scoped settings', async () => {
        const { dependencies, service } = createService()
        service.setProject(project('project-1'))

        await service.connect(configuredSettings())

        expect(dependencies.apiClient.validateProject).toHaveBeenCalledWith(expect.objectContaining({
            apiBaseUrl: 'https://sentry.example.com',
            apiToken: 'secret',
            environment: 'production',
            organization: 'acme',
            project: 'frontend',
        }))
        expect(service.getSnapshot()).toMatchObject({ errorMessage: null, isAuthenticated: true })
        expect(dependencies.storage.getItem(SENTRY_CONNECTION_STORAGE_KEY)).toContain('secret')
    })

    it('restores each project settings record independently', async () => {
        const { service } = createService()
        service.setProject(project('project-1'))
        await service.connect(configuredSettings({ organization: 'first' }))
        service.setProject(project('project-2'))

        expect(service.getSnapshot().settings.organization).toBe('')

        await service.connect(configuredSettings({ organization: 'second' }))
        service.setProject(project('project-1'))

        expect(service.getSnapshot().settings.organization).toBe('first')
        expect(service.getSnapshot().isAuthenticated).toBe(true)
    })

    it('does not persist settings when validation fails', async () => {
        const apiClient = { validateProject: vi.fn(async () => { throw new Error('Project not found') }) }
        const { dependencies, service } = createService({ apiClient })
        service.setProject(project('project-1'))

        await service.connect(configuredSettings())

        expect(dependencies.storage.getItem(SENTRY_CONNECTION_STORAGE_KEY)).toBeNull()
        expect(service.getSnapshot()).toMatchObject({ errorMessage: 'Project not found', isAuthenticated: false })
    })

    it('disconnects and removes token without writing project files', async () => {
        const { dependencies, service } = createService()
        service.setProject(project('project-1'))
        await service.connect(configuredSettings({ automaticImport: true }))

        service.disconnect()

        const stored = dependencies.storage.getItem(SENTRY_CONNECTION_STORAGE_KEY) ?? ''
        expect(stored).not.toContain('secret')
        expect(service.getSnapshot()).toMatchObject({ isAuthenticated: false })
        expect(service.getSnapshot().settings.automaticImport).toBe(false)
    })

    it('disconnects and retains a clear error after unauthorized API response', async () => {
        const { service } = createService()
        service.setProject(project('project-1'))
        await service.connect(configuredSettings())

        service.handleApiError(new SentryApiError('Unauthorized', 401))

        expect(service.getSnapshot()).toMatchObject({
            errorMessage: 'Sentry authorization expired. Connect again.',
            isAuthenticated: false,
        })
        expect(service.getSnapshot().settings.apiToken).toBe('')
    })

    it('clears an existing persisted token when reconnect validation is unauthorized', async () => {
        const { dependencies, service } = createService()
        service.setProject(project('project-1'))
        await service.connect(configuredSettings())
        vi.mocked(dependencies.apiClient.validateProject).mockRejectedValue(new SentryApiError('Unauthorized', 401))

        await service.connect(configuredSettings({ apiToken: 'replacement' }))

        expect(service.getSnapshot()).toMatchObject({
            errorMessage: 'Sentry authorization expired. Connect again.',
            isAuthenticated: false,
        })
        expect(dependencies.storage.getItem(SENTRY_CONNECTION_STORAGE_KEY)).not.toContain('secret')
        expect(dependencies.storage.getItem(SENTRY_CONNECTION_STORAGE_KEY)).not.toContain('replacement')
    })
})

import {
